import { logError } from "@/lib/logger";

type GradeRow = {
  session_id: string;
  q_idx: number;
  [key: string]: unknown;
};

function isOnConflictConstraintError(error: unknown): boolean {
  const e = error as { code?: string; message?: string } | null;
  const message = e?.message || "";
  return (
    e?.code === "42P10" ||
    /no unique or exclusion constraint matching the ON CONFLICT specification/i.test(
      message
    )
  );
}

/**
 * Upsert grades by (session_id, q_idx).
 * Falls back to update-then-insert when DB is missing the unique constraint.
 */
export async function upsertGradesBySessionQuestion(
  supabase: {
    from: (table: string) => {
      upsert: (
        values: GradeRow[],
        options: { onConflict: string }
      ) => {
        select: (
          columns: string
        ) => Promise<{ data: Array<{ q_idx: number }> | null; error: unknown }>;
      };
      update: (value: GradeRow) => {
        eq: (column: string, value: string | number) => {
          eq: (column: string, value: string | number) => {
            select: (
              columns: string
            ) => Promise<{ data: Array<{ q_idx: number }> | null; error: unknown }>;
          };
        };
      };
      insert: (value: GradeRow) => {
        select: (
          columns: string
        ) => {
          single: () => Promise<{ data: { q_idx: number } | null; error: unknown }>;
        };
      };
    };
  },
  rows: GradeRow[],
  source: string
): Promise<number[]> {
  if (rows.length === 0) return [];

  const { data: upsertRows, error: upsertError } = await supabase
    .from("grades")
    .upsert(rows, { onConflict: "session_id,q_idx" })
    .select("q_idx");

  if (!upsertError) {
    return (upsertRows || []).map((row) => row.q_idx);
  }

  if (!isOnConflictConstraintError(upsertError)) {
    throw upsertError;
  }

  logError("[GRADES_UPSERT] Missing onConflict constraint, using fallback path", upsertError, {
    path: "lib/grades-upsert.ts",
    additionalData: { source, rows: rows.length },
  });

  const qIdxs: number[] = [];
  for (const row of rows) {
    const { data: updatedRows, error: updateError } = await supabase
      .from("grades")
      .update(row)
      .eq("session_id", row.session_id)
      .eq("q_idx", row.q_idx)
      .select("q_idx");

    if (updateError) throw updateError;

    if (updatedRows && updatedRows.length > 0) {
      qIdxs.push(row.q_idx);
      continue;
    }

    const { data: insertedRow, error: insertError } = await supabase
      .from("grades")
      .insert(row)
      .select("q_idx")
      .single();

    if (insertError) throw insertError;
    if (insertedRow) qIdxs.push(insertedRow.q_idx);
  }

  return qIdxs;
}

import { NextRequest } from "next/server";
import { currentUser } from "@/lib/get-current-user";
import { successJson, errorJson } from "@/lib/api-response";
import { auditLog } from "@/lib/audit";
import { logError } from "@/lib/logger";
import { validateUUID } from "@/lib/validate-params";
import { checkRateLimitAsync, RATE_LIMITS } from "@/lib/rate-limit";
import { bulkGradeCommitSchema, validateRequest } from "@/lib/validations";
import { upsertGradesBySessionQuestion } from "@/lib/grades-upsert";
import { requireBulkGradeAccess } from "@/lib/bulk-grade-access";
import { getBulkGradableQuestions } from "@/lib/bulk-grading";

const COMMITTING_STALE_MS = 2 * 60 * 1000;

export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ examId: string }> },
) {
  try {
    const { examId } = await params;
    const invalidId = validateUUID(examId, "examId");
    if (invalidId) return invalidId;

    const user = await currentUser();
    const body = await request.json();
    const validation = validateRequest(bulkGradeCommitSchema, body);
    if (!validation.success) {
      return errorJson("VALIDATION_ERROR", validation.error, 400);
    }

    const { grades } = validation.data;

    const rl = await checkRateLimitAsync(
      `bulk-grade-commit:${user?.id ?? "anon"}:${examId}`,
      RATE_LIMITS.general,
    );
    if (!rl.allowed) {
      return errorJson("RATE_LIMITED", "Too many requests. Please wait.", 429);
    }

    const access = await requireBulkGradeAccess(examId, user, {
      requireGradable: true,
    });
    if (!access.ok) return access.response;

    const supabase = access.ctx.supabase;

    // [QA CRITICAL] 2-step ownership check:
    // Step 1 — exam.instructor_id === user.id (done by requireBulkGradeAccess)
    // Step 2 — all session_ids in grades belong to this exam
    const uniqueSessionIds = [...new Set(grades.map((g) => g.session_id))];
    const { data: validSessions, error: sessionsError } = await supabase
      .from("sessions")
      .select("id")
      .in("id", uniqueSessionIds)
      .eq("exam_id", examId);

    if (sessionsError) {
      logError("bulk-grade commit: session ownership check failed", sessionsError, {
        path: `/api/exam/${examId}/bulk-grade/commit`,
      });
      return errorJson("INTERNAL_ERROR", "Failed to verify sessions", 500);
    }

    if ((validSessions?.length ?? 0) !== uniqueSessionIds.length) {
      return errorJson(
        "FORBIDDEN",
        "One or more session IDs do not belong to this exam",
        403,
      );
    }

    const caseQIdxes = new Set(
      getBulkGradableQuestions(access.ctx.exam).map((q) => q.qIdx),
    );
    if (grades.some((g) => !caseQIdxes.has(g.q_idx))) {
      return errorJson("VALIDATION_ERROR", "채점 대상 문제 점수만 확정할 수 있습니다.", 400);
    }

    // [HIGH-1] Block commit while grading is in progress
    const { data: currentSession } = await supabase
      .from("exam_grading_sessions")
      .select("status, calibration_status, grading_scope")
      .eq("exam_id", examId)
      .eq("instructor_id", access.ctx.user.id)
      .maybeSingle();

    if (currentSession?.status === "grading") {
      return errorJson("CONFLICT", "채점이 진행 중입니다. 완료 후 확정하세요.", 409);
    }
    if (currentSession?.calibration_status === "sample_grading") {
      return errorJson("CONFLICT", "샘플 가채점이 진행 중입니다. 전체 가채점 완료 후 확정하세요.", 409);
    }
    if (currentSession?.status !== "grading_done" || currentSession?.grading_scope !== "full") {
      return errorJson("VALIDATION_ERROR", "전체 가채점 완료 후 확정할 수 있습니다.", 400);
    }

    // Claim the commit before writing grades.
    const nowIso = new Date().toISOString();
    const { data: claimedSession, error: statusError } = await supabase
      .from("exam_grading_sessions")
      .update({ status: "committing", updated_at: nowIso })
      .eq("exam_id", examId)
      .eq("instructor_id", access.ctx.user.id)
      .in("status", ["draft", "grading_done"])
      .select("id, status")
      .maybeSingle();

    if (statusError) {
      logError("bulk-grade commit: status update failed", statusError, {
        path: `/api/exam/${examId}/bulk-grade/commit`,
      });
      return errorJson("INTERNAL_ERROR", "Failed to update grading session", 500);
    }

    if (!claimedSession) {
      const { data: existingSession, error: existingError } = await supabase
        .from("exam_grading_sessions")
        .select("id, status, updated_at")
        .eq("exam_id", examId)
        .eq("instructor_id", access.ctx.user.id)
        .maybeSingle();

      if (existingError) {
        logError("bulk-grade commit: status read failed", existingError, {
          path: `/api/exam/${examId}/bulk-grade/commit`,
        });
        return errorJson("INTERNAL_ERROR", "Failed to read grading session", 500);
      }

      if (!existingSession || existingSession.status === "committed") {
        return successJson({ ok: true, gradedCount: grades.length, alreadyCommitted: true });
      }

      if (existingSession.status === "committing") {
        const updatedAt = existingSession.updated_at
          ? new Date(existingSession.updated_at as string).getTime()
          : 0;
        const isStale = !Number.isFinite(updatedAt) ||
          Date.now() - updatedAt > COMMITTING_STALE_MS;

        if (!isStale) {
          return errorJson("COMMIT_IN_PROGRESS", "Bulk grade commit is already in progress", 409);
        }

        const { data: reclaimedSession, error: reclaimError } = await supabase
          .from("exam_grading_sessions")
          .update({ updated_at: nowIso })
          .eq("id", existingSession.id)
          .eq("status", "committing")
          .select("id, status")
          .maybeSingle();

        if (reclaimError || !reclaimedSession) {
          logError("bulk-grade commit: stale committing reclaim failed", reclaimError, {
            path: `/api/exam/${examId}/bulk-grade/commit`,
          });
          return errorJson("COMMIT_IN_PROGRESS", "Bulk grade commit is already in progress", 409);
        }
      }
    }

    // Upsert grades
    const gradeRows = grades.map((g) => ({
      session_id: g.session_id,
      q_idx: g.q_idx,
      score: Math.min(100, Math.max(0, g.score)),
      comment: g.comment ?? "",
      stage_grading: {
        answer: {
          score: g.score,
          comment: g.comment ?? "",
        },
      },
      grade_type: "manual",
    }));

    try {
      await upsertGradesBySessionQuestion(
        supabase as never,
        gradeRows,
        "bulk_grade_commit",
      );
    } catch (upsertError) {
      await supabase
        .from("exam_grading_sessions")
        .update({ status: "draft", updated_at: new Date().toISOString() })
        .eq("exam_id", examId)
        .eq("instructor_id", access.ctx.user.id)
        .eq("status", "committing");
      throw upsertError;
    }

    const { error: commitError } = await supabase
      .from("exam_grading_sessions")
      .update({
        status: "committed",
        committed_at: new Date().toISOString(),
        updated_at: new Date().toISOString(),
      })
      .eq("exam_id", examId)
      .eq("instructor_id", access.ctx.user.id)
      .eq("status", "committing");

    if (commitError) {
      logError("bulk-grade commit: final status update failed", commitError, {
        path: `/api/exam/${examId}/bulk-grade/commit`,
      });
      return errorJson("INTERNAL_ERROR", "Failed to finalize grading session", 500);
    }

    try {
      await auditLog({
        action: "grade_bulk_commit",
        userId: access.ctx.user.id,
        targetId: examId,
        details: {
          gradedCount: grades.length,
          sessionIds: uniqueSessionIds.slice(0, 10),
          source: "bulk_grade_commit",
        },
      });
    } catch (auditError) {
      logError("[bulk-grade commit] Audit log failed", auditError, {
        path: `/api/exam/${examId}/bulk-grade/commit`,
      });
    }

    return successJson({ ok: true, gradedCount: grades.length });
  } catch (error) {
    logError("bulk-grade commit POST handler error", error, {
      path: "/api/exam/bulk-grade/commit",
    });
    return errorJson("INTERNAL_ERROR", "Internal server error", 500);
  }
}

import { NextRequest } from "next/server";
import { currentUser } from "@/lib/get-current-user";
import { successJson, errorJson } from "@/lib/api-response";
import { auditLog } from "@/lib/audit";
import { logError } from "@/lib/logger";
import { validateUUID } from "@/lib/validate-params";
import { checkRateLimitAsync, RATE_LIMITS } from "@/lib/rate-limit";
import {
  caseGradeCommitSchema,
  validateRequest,
} from "@/lib/validations";
import { upsertGradesBySessionQuestion } from "@/lib/grades-upsert";
import { requireCaseGradeAccess } from "@/lib/case-grade-access";

export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ sessionId: string }> },
) {
  try {
    const { sessionId } = await params;
    const invalidId = validateUUID(sessionId, "sessionId");
    if (invalidId) return invalidId;

    const user = await currentUser();
    const body = await request.json();
    const validation = validateRequest(caseGradeCommitSchema, body);
    if (!validation.success) {
      return errorJson("VALIDATION_ERROR", validation.error, 400);
    }

    const { qIdx, score, comment } = validation.data;

    const access = await requireCaseGradeAccess(sessionId, user, qIdx, {
      requireGradable: true,
    });
    if (!access.ok) return access.response;

    const rl = await checkRateLimitAsync(
      `case-grade-commit:${access.ctx.user.id}`,
      RATE_LIMITS.general,
    );
    if (!rl.allowed) {
      return errorJson("RATE_LIMITED", "Too many requests. Please wait.", 429);
    }

    const stageGrading = {
      answer: {
        score,
        comment: comment ?? "",
      },
    };

    await upsertGradesBySessionQuestion(
      access.ctx.supabase as never,
      [
        {
          session_id: sessionId,
          q_idx: qIdx,
          score,
          comment: comment ?? "",
          stage_grading: stageGrading,
          grade_type: "manual",
        },
      ],
      "case_grade_commit",
    );

    try {
      await auditLog({
        action: "grade_update",
        userId: access.ctx.user.id,
        targetId: sessionId,
        details: { qIdx, score, comment: comment?.slice(0, 200), source: "case_grade_commit" },
      });
    } catch (auditError) {
      logError("[case-grade commit] Audit log failed", auditError, {
        path: `/api/session/${sessionId}/case-grade/commit`,
      });
    }

    return successJson({ ok: true, qIdx, score });
  } catch (error) {
    logError("case-grade commit POST handler error", error, {
      path: "/api/session/case-grade/commit",
    });
    return errorJson("INTERNAL_ERROR", "Internal server error", 500);
  }
}

import { NextRequest } from "next/server";
import { getSupabaseServer } from "@/lib/supabase-server";
import { decompressData } from "@/lib/compression";
import { currentUser } from "@/lib/get-current-user";
import { triggerGradingIfNeeded } from "@/lib/grading-trigger";
import { successJson, errorJson } from "@/lib/api-response";
import { auditLog } from "@/lib/audit";
import { batchGetUserInfo } from "@/lib/app-users";
import { logError } from "@/lib/logger";
import { validateUUID } from "@/lib/validate-params";
import { checkRateLimitAsync, RATE_LIMITS } from "@/lib/rate-limit";
import { singleGradeUpdateSchema, validateRequest } from "@/lib/validations";
import { upsertGradesBySessionQuestion } from "@/lib/grades-upsert";
import {
  calculateScoreFromItems,
  deduplicateGrades,
  isSuccessfulGradeType,
  normalizeScoreWeights,
  type ScoreItem,
} from "@/lib/grade-utils";
import { hasQuestionWithQIdx } from "@/lib/case-grade-access";
import { gradeObjectiveAnswer, isObjectiveQuestion, isGradingOpen, isAssignmentType } from "@/lib/grading-helpers";
import { recordDemoGradedViewed } from "@/lib/demo-completion";

// Auto-grading (PUT) calls AI_MODEL_HEAVY multiple times — needs 300s
export const maxDuration = 300;

// P1-4: Supabase client created inside each handler (not module-level)
// to avoid stale connections in serverless cold starts.
// Same lazy getter pattern as submission-handlers.ts.
function getSupabase() {
  return getSupabaseServer();
}

export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ sessionId: string }> }
) {
  try {
    const { sessionId } = await params;

    const invalidId = validateUUID(sessionId, "sessionId");
    if (invalidId) return invalidId;

    const user = await currentUser();

    if (!user) {
      return errorJson("UNAUTHORIZED", "Unauthorized", 401);
    }

    // Check if user is instructor
    const userRole = user.role;
    if (userRole !== "instructor") {
      return errorJson("FORBIDDEN", "Forbidden", 403);
    }

    // Get session data first (including ai_summary for auto-graded summary)
    // ai_summary가 없을 수 있으므로 안전하게 처리
    const supabase = getSupabase();

    const { data: session, error: sessionError } = await supabase
      .from("sessions")
      .select("id, exam_id, student_id, submitted_at, used_clarifications, created_at, compressed_session_data, compression_metadata, ai_summary, auto_submitted, grading_progress, final_answer, final_answer_updated_at")
      .eq("id", sessionId)
      .single();

    if (sessionError || !session) {
      return errorJson("NOT_FOUND", "Session not found", 404, {
        details: sessionError?.message,
        sessionId,
      });
    }

    // Get exam data
    const { data: exam, error: examError } = await supabase
      .from("exams")
      .select("id, title, code, instructor_id, questions, rubric, status, score_weights, type, deadline")
      .eq("id", session.exam_id)
      .single();

    if (examError || !exam) {
      return errorJson("NOT_FOUND", "Exam not found", 404, {
        details: examError?.message,
      });
    }

    // Normalize questions format (text -> prompt); keep objective grading fields
    if (exam.questions && Array.isArray(exam.questions)) {
      exam.questions = exam.questions.map((q: Record<string, unknown>) => ({
        id: q.id,
        idx: q.idx,
        type: q.type,
        prompt: q.prompt || q.text, // Support both field names
        ai_context: q.ai_context,
        options: Array.isArray(q.options)
          ? (q.options as unknown[]).filter((o): o is string => typeof o === "string")
          : undefined,
        correctOptionIndex:
          typeof q.correctOptionIndex === "number" &&
          Number.isInteger(q.correctOptionIndex)
            ? q.correctOptionIndex
            : undefined,
      }));
    }

    // Optimized: Fetch submissions, messages, grades, paste_logs, and assignment quiz in parallel
    const [submissionsResult, messagesResult, gradesResult, pasteLogsResult, quizResult] =
      await Promise.all([
        supabase
          .from("submissions")
          .select(
            `
          id,
          q_idx,
          answer,
          compressed_answer_data,
          compression_metadata,
          created_at
        `
          )
          .eq("session_id", sessionId),
        supabase
          .from("messages")
          .select(
            `
          id,
          q_idx,
          role,
          content,
          compressed_content,
          compression_metadata,
          created_at
        `
          )
          .eq("session_id", sessionId),
        supabase
          .from("grades")
          .select(
            `
          id,
          q_idx,
          score,
          comment,
          stage_grading,
          ai_summary,
          grade_type,
          created_at
        `
          )
          .eq("session_id", sessionId),
        supabase
          .from("paste_logs")
          .select(
            `
          id,
          question_id,
          length,
          pasted_text,
          paste_start,
          paste_end,
          answer_length_before,
          is_internal,
          suspicious,
          timestamp,
          created_at
        `
          )
          .eq("session_id", sessionId)
          .order("timestamp", { ascending: true }),
        supabase
          .from("session_quiz_attempts")
          .select(
            `
          id,
          questions,
          answers,
          score,
          total_questions,
          time_limit_seconds,
          started_at,
          submitted_at,
          status
        `
          )
          .eq("session_id", sessionId)
          .maybeSingle(),
      ]);

    const { data: submissions, error: submissionsError } = submissionsResult;
    const { data: messages, error: messagesError } = messagesResult;
    const { data: grades, error: gradesError } = gradesResult;
    const { data: pasteLogs, error: pasteLogsError } = pasteLogsResult;
    const { data: quizAttempt, error: quizError } = quizResult;

    const path = `/api/session/${sessionId}/grade`;
    if (submissionsError) logError("Submissions query failed", submissionsError, { path, additionalData: { sessionId } });
    if (messagesError) logError("Messages query failed", messagesError, { path, additionalData: { sessionId } });
    if (gradesError) logError("Grades query failed", gradesError, { path, additionalData: { sessionId } });
    if (pasteLogsError) logError("PasteLogs query failed", pasteLogsError, { path, additionalData: { sessionId } });
    if (quizError) logError("Assignment quiz query failed", quizError, { path, additionalData: { sessionId } });

    // Check if instructor owns the exam
    if (exam.instructor_id !== user.id) {
      return errorJson("FORBIDDEN", "Forbidden", 403);
    }

    // Get student info from Clerk (batch call for consistency)
    const clerkUserMap = await batchGetUserInfo([session.student_id]);
    const clerkStudentInfo = clerkUserMap.get(session.student_id) ?? null;

    // Get student profile from database
    const { data: studentProfile } = await supabase
      .from("student_profiles")
      .select("name, student_number, school")
      .eq("student_id", session.student_id)
      .single();

    // Merge Clerk info with profile info (prefer profile name if available)
    const studentInfo = {
      name:
        studentProfile?.name ||
        clerkStudentInfo?.name ||
        `Student ${session.student_id.slice(0, 8)}`,
      email: clerkStudentInfo?.email || `${session.student_id}@example.com`,
      student_number: studentProfile?.student_number,
      school: studentProfile?.school,
    };

    // Decompress session data if available — track errors for frontend warning
    const decompressionErrors: Array<{ target: string; error: string }> = [];
    let decompressedSessionData = null;
    if (
      session.compressed_session_data &&
      typeof session.compressed_session_data === "string"
    ) {
      try {
        decompressedSessionData = decompressData(
          session.compressed_session_data
        );
      } catch (error) {
        const errMsg = error instanceof Error ? error.message : "Unknown decompression error";
        decompressionErrors.push({ target: "sessionData", error: errMsg });
        logError("Error decompressing session data", error, {
          path: `/api/session/${sessionId}/grade`,
        });
      }
    }

    // Decompress and organize submissions by question index
    const submissionsByQuestion: Record<string, unknown> = {};
    if (submissions) {
      submissions.forEach((submission: Record<string, unknown>) => {
        const qIdx = submission.q_idx as number;
        let decompressedAnswerData = null;

        if (
          submission.compressed_answer_data &&
          typeof submission.compressed_answer_data === "string"
        ) {
          try {
            decompressedAnswerData = decompressData(
              submission.compressed_answer_data as string
            );
          } catch (error) {
            const errMsg = error instanceof Error ? error.message : "Unknown decompression error";
            decompressionErrors.push({ target: `submission_q${qIdx}`, error: errMsg });
            logError("Error decompressing answer data", error, {
              path: `/api/session/${sessionId}/grade`,
            });
          }
        }

        submissionsByQuestion[qIdx] = {
          ...submission,
          decompressed: {
            answerData: decompressedAnswerData,
          },
        };
      });
    }

    // Organize messages by question index and separate AI conversation and feedback
    const messagesByQuestion: Record<string, unknown> = {};
    if (messages) {
      messages.forEach((message: Record<string, unknown>) => {
        const qIdx = message.q_idx as number;
        let decompressedContent = null;

        if (
          message.compressed_content &&
          typeof message.compressed_content === "string"
        ) {
          try {
            decompressedContent = decompressData(
              message.compressed_content as string
            );
          } catch (error) {
            const errMsg = error instanceof Error ? error.message : "Unknown decompression error";
            decompressionErrors.push({ target: `message_q${qIdx}_${message.id}`, error: errMsg });
            logError("Error decompressing message content", error, {
              path: `/api/session/${sessionId}/grade`,
            });
          }
        }

        const messageData = {
          id: message.id,
          role: message.role,
          content: decompressedContent || message.content,
          created_at: message.created_at,
        };

        // Store by q_idx
        if (!messagesByQuestion[qIdx]) {
          messagesByQuestion[qIdx] = [];
        }
        (messagesByQuestion[qIdx] as Array<Record<string, unknown>>).push(
          messageData
        );
        // NOTE: 과거엔 여기서 question.id 를 parseInt 로 정수화해 q_idx 와 매칭하는
        // "backward compatibility" 블록이 있었으나, question.id 가 crypto.randomUUID()
        // 라 UUID 앞자리 숫자가 우연히 다른 q_idx 와 충돌하면(실측 ~27%) A 문항의 대화가
        // B 문항에 복제되어 강사가 엉뚱한 대화를 보고 채점하는 데이터 오염을 유발했다.
        // 메시지는 위에서 q_idx(배열 위치)로 정확히 저장되고, 프론트는 resolveByQIdx
        // fallback 으로 idx/배열위치를 모두 커버하므로 해당 추측성 매핑을 제거한다.
      });

      // Sort messages by created_at within each question
      Object.keys(messagesByQuestion).forEach((qIdx) => {
        (messagesByQuestion[qIdx] as Array<Record<string, unknown>>).sort(
          (a: Record<string, unknown>, b: Record<string, unknown>) =>
            new Date(a.created_at as string).getTime() -
            new Date(b.created_at as string).getTime()
        );
      });
    }

    // Organize grades by question index
    const gradesByQuestion: Record<string, unknown> = {};
    if (grades) {
      grades.forEach((grade: Record<string, unknown>) => {
        const qIdx = grade.q_idx as number;
        gradesByQuestion[qIdx] = grade;
      });
    }

    // Organize paste logs by question_id
    const pasteLogsByQuestion: Record<string, unknown[]> = {};
    if (pasteLogs) {
      pasteLogs.forEach((log: Record<string, unknown>) => {
        const questionId = log.question_id as string;
        if (questionId) {
          if (!pasteLogsByQuestion[questionId]) {
            pasteLogsByQuestion[questionId] = [];
          }
          pasteLogsByQuestion[questionId].push(log);
        }
      });
    }

    // Calculate overall score if grades exist
    let overallScore = null;
    if (isGradingOpen(exam) && Array.isArray(exam.questions)) {
      const scoreWeights = normalizeScoreWeights(exam.score_weights);
      const gradeByQ = new Map(
        deduplicateGrades(grades ?? [])
          .filter((grade) => isSuccessfulGradeType(grade.grade_type))
          .map((grade) => [grade.q_idx, grade])
      );
      const scoreItems: ScoreItem[] = exam.questions.map(
        (question: { idx?: number; type?: string; options?: string[]; correctOptionIndex?: number }, index: number) => {
          const qIdx = typeof question.idx === "number" ? question.idx : index;
          if (isObjectiveQuestion(question.type)) {
            const submission = submissionsByQuestion[qIdx] as
              | { answer?: string }
              | undefined;
            const objective = gradeObjectiveAnswer({
              rawAnswer: submission?.answer ?? "",
              options: question.options,
              correctOptionIndex: question.correctOptionIndex,
            });
            return { qIdx, type: question.type, score: objective?.score };
          }
          const grade = gradeByQ.get(qIdx);
          return { qIdx, type: question.type, score: grade?.score };
        }
      );
      const scoreResult = calculateScoreFromItems(scoreItems, scoreWeights);
      overallScore =
        scoreResult.overallScore !== null &&
        (scoreResult.mode === "weighted" || scoreResult.gradedCount > 0)
          ? scoreResult.overallScore
          : null;
    }

    const responseData = {
      session: {
        id: session.id,
        exam_id: session.exam_id,
        student_id: session.student_id,
        submitted_at: session.submitted_at,
        used_clarifications: session.used_clarifications,
        created_at: session.created_at,
        decompressed: decompressedSessionData,
        ai_summary: session.ai_summary || null, // 서버 사이드 자동 채점 요약 평가
        auto_submitted: session.auto_submitted || false, // 강제 종료로 자동 제출된 세션
        grading_progress: session.grading_progress || null, // QStash 진행률 상태 ({ status, total, completed, failed })
        final_answer: session.final_answer ?? null,
        final_answer_updated_at: session.final_answer_updated_at ?? null,
      },
      exam: exam,
      student: studentInfo,
      submissions: submissionsByQuestion,
      messages: messagesByQuestion,
      grades: gradesByQuestion, // 서버 사이드 자동 채점 점수
      pasteLogs: pasteLogsByQuestion, // 부정행위 의심 로그 (question_id별로 그룹화)
      overallScore,
      aiSummary: session.ai_summary || null, // 하위 호환성을 위해 유지
      assignmentQuiz: quizAttempt || null,
      gradingProgress: session.grading_progress || null, // 실시간 채점 진행률
      ...(decompressionErrors.length > 0 && { decompressionErrors }),
    };

    try {
      await recordDemoGradedViewed({
        userId: exam.instructor_id,
        examId: exam.id,
        hasGrades: Array.isArray(grades) && grades.length > 0,
      });
    } catch (error) {
      // 계측 장애가 실제 채점 결과 열람을 500으로 바꾸면 완주보다 더 큰 학습 흐름이 끊긴다.
      logError("Failed to record demo completion", error, { path });
    }

    return successJson(responseData, {
      headers: { "Cache-Control": "private, max-age=60, stale-while-revalidate=120" },
    });
  } catch (error) {
    logError("Grade GET handler error", error, {
      path: `/api/session/grade`,
    });
    return errorJson(
      "INTERNAL_ERROR",
      process.env.NODE_ENV === "development"
        ? (error as Error)?.message || "Internal server error"
        : "Internal server error",
      500
    );
  }
}

// Save or update grades
export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ sessionId: string }> },
) {
  try {
    const { sessionId } = await params;

    const invalidId = validateUUID(sessionId, "sessionId");
    if (invalidId) return invalidId;

    const supabase = getSupabase();
    const user = await currentUser();
    const body = await request.json();

    // Validate POST body with schema
    const validation = validateRequest(singleGradeUpdateSchema, body);
    if (!validation.success) {
      return errorJson("VALIDATION_ERROR", validation.error, 400);
    }
    const { questionIdx, score, comment, stageGrading, expected_updated_at } = validation.data;

    if (!user) {
      return errorJson("UNAUTHORIZED", "Unauthorized", 401);
    }

    // Check if user is instructor
    const userRole = user.role;
    if (userRole !== "instructor") {
      return errorJson("FORBIDDEN", "Forbidden", 403);
    }

    // Get session to verify instructor owns the exam
    const { data: session, error: sessionError } = await supabase
      .from("sessions")
      .select("id, exam_id")
      .eq("id", sessionId)
      .single();

    if (sessionError || !session) {
      return errorJson("NOT_FOUND", "Session not found", 404);
    }

    // Get exam to check instructor and validate q_idx upper bound
    const { data: exam, error: examError } = await supabase
      .from("exams")
      .select("instructor_id, questions, status, type, deadline")
      .eq("id", session.exam_id)
      .single();

    if (examError || !exam) {
      return errorJson("NOT_FOUND", "Exam not found", 404);
    }

    // Check if instructor owns the exam
    if (exam.instructor_id !== user.id) {
      return errorJson("FORBIDDEN", "Forbidden", 403);
    }

    if (!isGradingOpen(exam)) {
      return isAssignmentType(exam.type)
        ? errorJson("ASSIGNMENT_NOT_DUE", "과제 마감 후에 채점할 수 있습니다.", 409)
        : errorJson("EXAM_NOT_CLOSED", "시험 종료 후에 채점할 수 있습니다.", 409);
    }

    // Validate q_idx bounds against exam questions (P1-2: also reject negative)
    if (questionIdx < 0) {
      return errorJson("VALIDATION_ERROR", `Invalid question index: ${questionIdx}`, 400);
    }
    if (Array.isArray(exam.questions) && !hasQuestionWithQIdx(exam.questions, questionIdx)) {
      return errorJson("VALIDATION_ERROR", `Invalid question index: ${questionIdx}`, 400);
    }

    // Optimistic locking: if client sends expected_updated_at, verify no concurrent edit
    if (expected_updated_at) {
      const { data: existingGrade } = await supabase
        .from("grades")
        .select("created_at")
        .eq("session_id", sessionId)
        .eq("q_idx", questionIdx)
        .single();

      if (existingGrade && existingGrade.created_at !== expected_updated_at) {
        return errorJson("CONFLICT", "Grade was modified by another user. Please refresh and try again.", 409);
      }
    }

    // Upsert grade with fallback for environments missing UNIQUE(session_id, q_idx)
    await upsertGradesBySessionQuestion(
      supabase as never,
      [
        {
          session_id: sessionId,
          q_idx: questionIdx,
          score,
          comment,
          stage_grading: stageGrading || null,
          grade_type: "manual",
        },
      ],
      "manual_grade_post"
    );

    const { data: result, error: fetchGradeError } = await supabase
      .from("grades")
      .select("*")
      .eq("session_id", sessionId)
      .eq("q_idx", questionIdx)
      .order("created_at", { ascending: false })
      .limit(1)
      .maybeSingle();

    if (fetchGradeError) throw fetchGradeError;

    // Audit log: fire-and-forget with error catching
    try {
      await auditLog({
        action: "grade_update",
        userId: user.id,
        targetId: sessionId,
        details: { questionIdx, score, comment: comment?.slice(0, 200) },
      });
    } catch (auditError) {
      // Log but don't block the response
      logError("[grade] Audit log failed", auditError, { path: `/api/session/${sessionId}/grade` });
    }

    return successJson({
      grade: result,
    });
  } catch (error) {
    logError("Grade POST handler error", error, {
      path: `/api/session/grade`,
    });
    return errorJson(
      "INTERNAL_ERROR",
      process.env.NODE_ENV === "development"
        ? (error as Error)?.message || "Internal server error"
        : "Internal server error",
      500
    );
  }
}

// Auto-grade all questions based on rubric — delegates to autoGradeSession()
export async function PUT(
  request: NextRequest,
  { params }: { params: Promise<{ sessionId: string }> }
) {
  try {
    const { sessionId } = await params;

    const invalidId = validateUUID(sessionId, "sessionId");
    if (invalidId) return invalidId;

    const supabase = getSupabase();
    const user = await currentUser();
    const body = await request.json().catch(() => ({}));
    const { forceRegrade = false } = body;

    if (!user) {
      return errorJson("UNAUTHORIZED", "Unauthorized", 401);
    }

    const userRole = user.role;
    if (userRole !== "instructor") {
      return errorJson("FORBIDDEN", "Forbidden", 403);
    }

    // Verify session exists and instructor owns the exam
    const { data: session, error: sessionError } = await supabase
      .from("sessions")
      .select("id, exam_id")
      .eq("id", sessionId)
      .single();

    if (sessionError || !session) {
      return errorJson("NOT_FOUND", "Session not found", 404);
    }

    const { data: exam, error: examError } = await supabase
      .from("exams")
      .select("instructor_id, status, type, deadline")
      .eq("id", session.exam_id)
      .single();

    if (examError || !exam || exam.instructor_id !== user.id) {
      return errorJson("FORBIDDEN", "Forbidden", 403);
    }

    if (!isGradingOpen(exam)) {
      return isAssignmentType(exam.type)
        ? errorJson("ASSIGNMENT_NOT_DUE", "과제 마감 후에 채점할 수 있습니다.", 409)
        : errorJson("EXAM_NOT_CLOSED", "시험 종료 후에 채점할 수 있습니다.", 409);
    }

    // Rate limit: expensive OpenAI auto-grading
    const rl = await checkRateLimitAsync(`ai:auto-grade:${user.id}`, RATE_LIMITS.ai);
    if (!rl.allowed) {
      return errorJson("RATE_LIMITED", "Too many grading requests. Please wait.", 429);
    }

    // Check if already graded (unless force regrade)
    // forceRegrade path uses QStash re-publish; idempotency guard is skipped there.
    if (!forceRegrade) {
      const { data: existingGrades } = await supabase
        .from("grades")
        .select("q_idx, grade_type")
        .eq("session_id", sessionId);

      const hasSuccessfulGrade = existingGrades?.some(
        (g) => isSuccessfulGradeType(g.grade_type)
      );

      if (hasSuccessfulGrade) {
        return successJson({ message: "Already graded", skipped: true });
      }
    }

    // Reset grading_progress to queued so the UI shows progress immediately
    // while QStash (or in-process fallback) picks up the job.
    await supabase
      .from("sessions")
      .update({
        grading_progress: {
          status: "queued",
          total: 0,
          completed: 0,
          failed: 0,
          updated_at: new Date().toISOString(),
        },
      })
      .eq("id", sessionId);

    // Clear prior grading_status marker so triggerGradingIfNeeded won't short-circuit
    if (forceRegrade) {
      const { data: sessForSummary } = await supabase
        .from("sessions")
        .select("ai_summary")
        .eq("id", sessionId)
        .maybeSingle();
      const prior = (sessForSummary?.ai_summary as Record<string, unknown> | null) || null;
      if (prior && "grading_status" in prior) {
        // Strip grading_status fields but keep any human summary content for reference.
        const {
          grading_status: _s,
          grading_failed_questions: _f,
          grading_completed_count: _c,
          grading_total_count: _t,
          grading_timed_out: _to,
          grading_failure_details: _d,
          ...rest
        } = prior;
        void _s; void _f; void _c; void _t; void _to; void _d;
        await supabase
          .from("sessions")
          .update({ ai_summary: Object.keys(rest).length > 0 ? rest : null })
          .eq("id", sessionId);
      }
    }

    // Enqueue via QStash (durable) or in-process fallback
    const triggerResult = await triggerGradingIfNeeded(sessionId, "manual_retry", {
      skipIdempotency: true,
    });

    return successJson({
      queued: triggerResult.queued,
      reason: triggerResult.reason,
    });
  } catch (error) {
    logError("Grade PUT handler error", error, {
      path: `/api/session/grade`,
    });
    return errorJson(
      "INTERNAL_ERROR",
      process.env.NODE_ENV === "development"
        ? (error as Error)?.message || "Unknown error occurred"
        : "Internal server error",
      500
    );
  }
}

/**
 * bulk-grade 점수 범위 clamp 회귀 가드.
 *
 * 버그: 재보정(anti-clustering) 경로가 강사 지정 score_range 를 clamp 하지 않고
 * AI 점수를 그대로 저장할 수 있었다(원본 채점 경로는 clamp 함). 이제 두 경로가
 * 공유 clampScore 를 쓴다. 이 테스트는 점수가 강사 지정 min/max 를 벗어나지 않음을 잠근다.
 */
import { describe, expect, it } from "vitest";
import { clampScore } from "@/lib/bulk-grade-score-cluster";

describe("clampScore — 강사 지정 범위 강제", () => {
  it("범위(60~90) 밖 낮은 점수는 min 으로 올린다", () => {
    expect(clampScore(45, { min: 60, max: 90 })).toBe(60);
  });

  it("범위(60~90) 밖 높은 점수는 max 로 내린다", () => {
    expect(clampScore(100, { min: 60, max: 90 })).toBe(90);
  });

  it("범위 안 점수는 반올림만 한다", () => {
    expect(clampScore(72.4, { min: 60, max: 90 })).toBe(72);
    expect(clampScore(72.6, { min: 60, max: 90 })).toBe(73);
  });

  it("범위 미지정 시 기본 0~100 을 적용한다", () => {
    expect(clampScore(-10)).toBe(0);
    expect(clampScore(150)).toBe(100);
    expect(clampScore(55)).toBe(55);
  });

  it("min===max 이면 항상 그 값으로 고정된다", () => {
    expect(clampScore(30, { min: 80, max: 80 })).toBe(80);
    expect(clampScore(999, { min: 80, max: 80 })).toBe(80);
  });

  it("경계값은 그대로 유지된다", () => {
    expect(clampScore(60, { min: 60, max: 90 })).toBe(60);
    expect(clampScore(90, { min: 60, max: 90 })).toBe(90);
  });
});

